class Solution:

	def flatten(self, root):
		stack = [(root, False)]
		dummy = Node(-1)
		curr = dummy
		while stack:
			(node, visited) = stack.pop()
			if visited:
				curr.right = node
				node.left = None
				curr = node
			elif node:
				stack.append((node.right, False))
				stack.append((node.left, False))
				stack.append((node, True))
		return dummy
